public record Line(string Name, long Price = 25L, int Quantity = 1) {
 public long Total => Price * Quantity;
 public Line() : this("default") {}
}
string Name() { Print("name"); return "Ada"; }
int Count() { Print("count"); return 3; }
void Main() {
 var a = new Line(Quantity: Count(), Name: Name());
 var b = new Line("Ada", 25L, 3);
 Print(a.Total); Print(a == b); Print(a.Equals(b)); Print(a.GetHashCode() == b.GetHashCode());
 var c = a with { Quantity = 4 }; Print(c.Total); Print(a.Quantity); Print(c != a);
 Print(new Line().Name);
}
